<script setup lang="ts">import{ref}from'vue';import{useRouter,useRoute}from'vue-router';import{useAuth}from'../stores/auth';const username=ref(''),password=ref(''),error=ref(''),busy=ref(false),router=useRouter(),route=useRoute(),auth=useAuth();async function submit(){busy.value=true;error.value='';try{await auth.login(username.value,password.value);router.replace(String(route.query.redirect||'/admin'))}catch(e:any){error.value=e.message}finally{busy.value=false}}</script><template><div class="login"><form class="panel" @submit.prevent="submit"><RouterLink to="/" class="logo">&gt; SHINO.LOG_</RouterLink><h1>管理员登录</h1><p>进入 After Compile 控制台</p><label>用户名<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required minlength="8"></label><p v-if="error" class="error" role="alert">{{error}}</p><button :disabled="busy">{{busy?'正在验证…':'登录'}}</button></form></div></template>
